create table merchant_pricing_policies (id uuid primary key, merchant_id text not null, version integer not null, policy jsonb not null, created_at timestamptz not null, unique (merchant_id, version));
create table comparison_requests (id uuid primary key, merchant_id text not null, session_id uuid not null, product_id text not null, quantity integer not null check (quantity > 0), cart_fingerprint text not null, source_type text not null check (source_type in ('live','fixture','cached')), status text not null, created_at timestamptz not null, completed_at timestamptz);
create table competitor_evidence (id uuid primary key, comparison_id uuid not null references comparison_requests(id), evidence jsonb not null, retrieved_at timestamptz not null);
create table authorized_offers (id uuid primary key, comparison_id uuid not null references comparison_requests(id), merchant_id text not null, session_id uuid not null, product_id text not null, variant_key text not null, quantity integer not null check (quantity > 0), cart_fingerprint text not null, currency char(3) not null, original_unit_minor bigint not null, approved_unit_minor bigint not null, final_total_minor bigint not null, policy_id text not null, policy_version integer not null, evidence_snapshot jsonb not null, status text not null check (status in ('issued','accepted','consumed','expired','revoked')), created_at timestamptz not null, expires_at timestamptz not null, accepted_at timestamptz, consumed_at timestamptz);
create table offer_acceptances (id uuid primary key, offer_id uuid not null unique references authorized_offers(id), merchant_id text not null, session_id uuid not null, cart_fingerprint text not null, accepted_at timestamptz not null);
create index authorized_offers_owner_idx on authorized_offers (merchant_id, session_id, status);
alter table merchant_pricing_policies enable row level security;
alter table comparison_requests enable row level security;
alter table competitor_evidence enable row level security;
alter table authorized_offers enable row level security;
alter table offer_acceptances enable row level security;
